package io.knowledgebrain.gateway;
import java.net.http.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class GroupMembershipProxyTest {
 GatewayTransport transport;GatewayController proxy;String id="01a10000-0000-7000-8000-000000000000",root="/api/groups/"+id;
 @BeforeEach @SuppressWarnings("unchecked") void init()throws Exception{transport=mock(GatewayTransport.class);proxy=new GatewayController(transport,new SimpleMeterRegistry(),"https://localhost:8443");HttpResponse<byte[]> r=mock(HttpResponse.class);when(r.statusCode()).thenReturn(200);when(r.body()).thenReturn("{}".getBytes());when(r.headers()).thenReturn(HttpHeaders.of(Map.of("Content-Type",List.of("application/json")),(a,b)->true));when(transport.send(any(),anyString(),anyMap(),any())).thenReturn(r);}
 MockHttpServletRequest request(String method,String path){var r=new MockHttpServletRequest(method,path);r.setSecure(true);r.addHeader("Origin","https://localhost:8443");r.setContentType("application/json");return r;}
 @Test void exactRoutesPreserveServiceOwnership(){for(String path:List.of(root+"/members",root+"/invitations",root+"/membership",root+"/members/"+id+"/revisions",root+"/invitations/"+id+"/revisions"))assertEquals("space",GatewayRoute.select("GET",path).service());assertEquals("space",GatewayRoute.select("POST","/api/group-invitations/accept").service());assertEquals("space",GatewayRoute.select("PUT",root+"/members/"+id).service());assertEquals("collaboration",GatewayRoute.select("GET","/api/groups/participating").service());assertEquals("collaboration",GatewayRoute.select("GET",root+"/participation").service());for(String path:List.of("/internal/space/group-participation",root+"/members/"+id+"/owner","/api/group-invitations/accept?code=secret"))assertNull(GatewayRoute.select("GET",path));assertNull(GatewayRoute.select("PATCH",root+"/members/"+id));}
 @Test void issueRequiresSingletonKeyAndForwardsOnlyIntendedHeaders()throws Exception{assertThrows(ResponseStatusException.class,()->proxy.proxy(request("POST",root+"/invitations")));var r=request("POST",root+"/invitations");r.addHeader("Idempotency-Key","a".repeat(32));r.addHeader("Authorization","Bearer forged");r.setContent("{}".getBytes());proxy.proxy(r);verify(transport).send(eq(new GatewayRoute("space",root+"/invitations")),eq("POST"),argThat(h->h.get("Idempotency-Key").equals(List.of("a".repeat(32)))&&!h.containsKey("Authorization")),any());}
 @Test void bodiesAmbiguousQueriesAndCodeInUrlAreDenied(){for(String path:List.of(root+"/members",root+"/membership")){var r=request("GET",path);r.setContent("{}".getBytes());assertThrows(ResponseStatusException.class,()->proxy.proxy(r));}for(String query:List.of("code=secret","limit=101","after="+id+"&after="+id)){var r=request("GET",root+"/invitations");r.setQueryString(query);assertThrows(ResponseStatusException.class,()->proxy.proxy(r));}var accept=request("POST","/api/group-invitations/accept");accept.setQueryString("code=secret");assertThrows(ResponseStatusException.class,()->proxy.proxy(accept));verifyNoInteractions(transport);}
 @Test void versionAndParticipationCursorAreForwarded()throws Exception{var r=request("PUT",root+"/members/"+id);r.addHeader("If-Match","\"gm2\"");proxy.proxy(r);verify(transport).send(eq(new GatewayRoute("space",root+"/members/"+id)),eq("PUT"),argThat(h->h.get("If-Match").equals(List.of("\"gm2\""))),any());var page=request("GET","/api/groups/participating");page.setQueryString("after="+id+"&limit=20");proxy.proxy(page);verify(transport).send(eq(new GatewayRoute("collaboration","/api/groups/participating?after="+id+"&limit=20")),eq("GET"),anyMap(),any());}
}
